program CotChain implements ISolve {
    public function solve(mention: str): str {
        create frame: number;
        bind frame, H1_PARENT_TAXON, "Iridomyrmex";
        bind frame, H2_INSTANCE, "Taxxon";
        bind frame, H3_COMPONENT, "Books/Organism";
        return recover(frame, H1_PARENT_TAXON);
    }

    public function hop_2(): str {
        create frame: number;
        bind frame, H1_PARENT_TAXON, "Iridomyrmex";
        bind frame, H2_INSTANCE, "Taxxon";
        bind frame, H3_COMPONENT, "Books/Organism";
        return recover(frame, H2_INSTANCE);
    }

    public function hop_3(): str {
        create frame: number;
        bind frame, H1_PARENT_TAXON, "Iridomyrmex";
        bind frame, H2_INSTANCE, "Taxxon";
        bind frame, H3_COMPONENT, "Books/Organism";
        return recover(frame, H3_COMPONENT);
    }

    public function control(): str {
        create frame: number;
        bind frame, H1_PARENT_TAXON, "Iridomyrmex";
        bind frame, H2_INSTANCE, "Taxxon";
        bind frame, H3_COMPONENT, "Books/Organism";
        return recover(frame, ABSENT_CTRL);
    }
}

